// Normaliza lo que mandó la app. Un audio pasa como archivo binario para la transcripción
const body = $('Chat de Wally').first().json.body ?? {};
const historial = (Array.isArray(body.history) ? body.history : [])
  .filter((m) => m && typeof m.text === 'string' && m.text.trim())
  .slice(-10)
  .map((m) => ({ role: m.role === 'model' ? 'assistant' : 'user', content: m.text.slice(0, 2000) }));

if (body.audio && body.audio.base64) {
  const mimeType = String(body.audio.mimeType || 'audio/webm').split(';')[0];
  const ext = { 'audio/webm': 'webm', 'audio/ogg': 'ogg', 'audio/mp4': 'mp4', 'audio/mpeg': 'mp3', 'audio/wav': 'wav', 'audio/x-m4a': 'm4a' }[mimeType] || 'webm';
  return [{
    json: { esAudio: true, historial },
    binary: { audio: { data: body.audio.base64, mimeType, fileName: 'audio.' + ext } },
  }];
}

const texto = typeof body.text === 'string' ? body.text.trim().slice(0, 2000) : '';
if (!texto) return [{ json: { vacio: true } }];
return [{ json: { esAudio: false, texto, historial } }];

// Arma el pedido al modelo de chat con la fecha y hora reales, el historial y el texto
// (escrito, o lo que transcribió Whisper)
const statusDe = (res) => {
  const err = res.error;
  return res.statusCode ?? (Number(
    err?.httpCode ?? err?.status ?? err?.response?.status ?? (String(err?.message ?? err ?? '').match(/\b([45]\d\d)\b/) || [])[1]
  ) || undefined);
};
const detalleDe = (res) => {
  const parse = (v) => { if (typeof v !== 'string') return v ?? {}; try { return JSON.parse(v); } catch { const m = v.replace(/\\"/g, '"').match(/\{[\s\S]*\}/); try { return m ? JSON.parse(m[0]) : {}; } catch { return {}; } } };
  const body = parse(res.body);
  const desc = parse(res.error?.description) ;
  const msg = parse(res.error?.message);
  return body.error?.message || desc.error?.message || msg.error?.message || res.error?.message || 'sin respuesta';
};
const fallo = (res, que) => {
  const status = statusDe(res);
  if (status === 429) return 'Llegué al límite de la IA por ahora. Probá de nuevo en un rato.';
  if (status >= 500) return 'La IA no responde en este momento. Probá de nuevo en unos segundos.';
  return 'No pude ' + que + ' (Groq ' + (status ?? '-') + ': ' + detalleDe(res) + ')';
};
const config = $('Config').first().json;
const p = $('Preparar pedido').first().json;

let texto = p.texto;
let transcript = '';
if (p.esAudio) {
  const res = $input.first().json;
  if (statusDe(res) !== 200) return [{ json: { listo: false, response: { text: fallo(res, 'escuchar el audio'), status: 'error' } } }];
  transcript = String(res.body?.text ?? '').trim();
  if (!transcript) return [{ json: { listo: false, response: { text: 'No escuché nada en el audio. ¿Me lo repetís?', status: 'error' } } }];
  texto = transcript;
}

// Resistencia, Chaco (UTC-3, sin horario de verano). Siempre la hora real del servidor, nunca la del modelo
const tz = 'America/Argentina/Cordoba';
const ahora = new Date();
const hoy = new Intl.DateTimeFormat('en-CA', { timeZone: tz, year: 'numeric', month: '2-digit', day: '2-digit' }).format(ahora);
const hora = new Intl.DateTimeFormat('en-GB', { timeZone: tz, hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).format(ahora);
const fechaLarga = new Intl.DateTimeFormat('es-AR', { timeZone: tz, weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' }).format(ahora);

const instrucciones = [
  'Sos Wally, un asistente que anota los gastos e ingresos de una persona de Argentina.',
  'Ahora es ' + fechaLarga + ', ' + hora + ' hs (' + hoy + ', hora de Resistencia, Chaco, Argentina, UTC-3). Usá siempre esta fecha y hora como "ahora"; no supongas otra.',
  'Los mensajes pueden venir de un audio transcripto automáticamente, con errores de transcripción y modismos: "lucas" o "luquitas" son miles, "palo" es un millón.',
  '',
  'Elegí una acción:',
  '- "guardar": el mensaje describe un gasto o ingreso y el monto está claro.',
  '- "preguntar": describe un movimiento pero falta el monto; preguntá solo lo que falta. Usá el historial para completar datos dichos antes.',
  '- "charlar": saludos u otra cosa; respondé breve y recordá que podés anotar gastos e ingresos.',
  '',
  'Campos del movimiento:',
  '- monto: número positivo, sin signos ni separadores de miles.',
  '- motivo: corto, qué fue (ej. "Supermercado", "Sueldo", "Nafta").',
  '- tipo: "gasto" o "ingreso".',
  '- categoria: una de ' + config.categorias + '.',
  '- fecha: YYYY-MM-DD. Resolvé "ayer", "anoche", "el viernes", "el 3", etc. respecto de ahora. Si no la dice, es hoy. Nunca una fecha futura salvo que lo diga explícitamente.',
  '- hora: HH:MM (24 hs) solo si dice cuándo fue ("a las 9", "al mediodía", "anoche" ≈ 22:00). Si no lo dice, "".',
  '- observacion: detalles extra que haya dicho (con quién, dónde, forma de pago, en cuotas, etc.). "" si no hay.',
  '',
  'respuesta: texto breve en español rioplatense (voseo) para mostrarle. Si la acción es "guardar", NO digas que ya lo anotaste: la persona lo revisa y lo confirma; decí algo como "¿Lo guardo así?".',
  '',
  'Respondé SOLO con un objeto JSON con esta forma:',
  '{"accion": "guardar" | "preguntar" | "charlar", "respuesta": "...", "movimiento": {"monto": 0, "motivo": "", "tipo": "gasto", "categoria": "", "fecha": "YYYY-MM-DD", "hora": "", "observacion": ""} | null}',
].join('\n');

const chatRequest = {
  model: config.modeloChat,
  temperature: 0.2,
  response_format: { type: 'json_object' },
  messages: [{ role: 'system', content: instrucciones }, ...p.historial, { role: 'user', content: texto }],
};
// Los modelos gpt-oss razonan antes de responder; con poco esfuerzo alcanza y responde más rápido
if (String(config.modeloChat).startsWith('openai/gpt-oss')) chatRequest.reasoning_effort = 'low';

return [{ json: { listo: true, chatRequest, transcript, hoy, hora } }];

// Lee la respuesta del modelo y arma el borrador del movimiento. No guarda nada:
// la app lo muestra para que la persona lo revise, edite o confirme
const statusDe = (res) => {
  const err = res.error;
  return res.statusCode ?? (Number(
    err?.httpCode ?? err?.status ?? err?.response?.status ?? (String(err?.message ?? err ?? '').match(/\b([45]\d\d)\b/) || [])[1]
  ) || undefined);
};
const detalleDe = (res) => {
  const parse = (v) => { if (typeof v !== 'string') return v ?? {}; try { return JSON.parse(v); } catch { const m = v.replace(/\\"/g, '"').match(/\{[\s\S]*\}/); try { return m ? JSON.parse(m[0]) : {}; } catch { return {}; } } };
  const body = parse(res.body);
  const desc = parse(res.error?.description) ;
  const msg = parse(res.error?.message);
  return body.error?.message || desc.error?.message || msg.error?.message || res.error?.message || 'sin respuesta';
};
const fallo = (res, que) => {
  const status = statusDe(res);
  if (status === 429) return 'Llegué al límite de la IA por ahora. Probá de nuevo en un rato.';
  if (status >= 500) return 'La IA no responde en este momento. Probá de nuevo en unos segundos.';
  return 'No pude ' + que + ' (Groq ' + (status ?? '-') + ': ' + detalleDe(res) + ')';
};
const res = $input.first().json;
const { hoy, hora: horaActual, transcript } = $('Armar pedido').first().json;
const error = (text) => [{ json: { response: { text, status: 'error', transcript } } }];

if (statusDe(res) !== 200) return error(fallo(res, 'hablar con la IA'));

let ia;
try {
  ia = JSON.parse(res.body?.choices?.[0]?.message?.content ?? '');
} catch {
  return error(transcript ? 'No te entendí bien el audio. ¿Me lo repetís?' : 'No te entendí. ¿Me lo decís de otra forma?');
}

const m = ia.movimiento;
const monto = Math.round(Math.abs(Number(m?.monto)) * 100) / 100;

if (ia.accion !== 'guardar' || !m || !(monto > 0)) {
  // "guardar" without a usable amount is really a question
  const pregunta = ia.accion === 'guardar' ? '¿De cuánto fue?' : '¿Qué querés anotar?';
  return [{ json: { response: { text: ia.respuesta || pregunta, status: 'success', transcript } } }];
}

const fecha = /^\d{4}-\d{2}-\d{2}$/.test(m.fecha || '') ? m.fecha : hoy;
const motivo = String(m.motivo || '').trim() || 'Sin motivo';
// Una hora futura de hoy es un error de la IA: se descarta
let hora = /^([01]\d|2[0-3]):[0-5]\d$/.test(m.hora || '') ? m.hora : '';
if (hora && fecha === hoy && hora > horaActual) hora = '';
const draft = {
  monto,
  descripcion: motivo.charAt(0).toUpperCase() + motivo.slice(1),
  tipo: m.tipo === 'ingreso' ? 'ingreso' : 'gasto',
  categoria: String(m.categoria || 'otros').toLowerCase().trim() || 'otros',
  fecha,
  hora,
  observacion: String(m.observacion || '').trim(),
};

return [{ json: { response: { text: ia.respuesta || '¿Lo guardo así?', status: 'success', transcript, draft } } }];
